[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$JobRoot)
$ErrorActionPreference='Stop';$JobRoot=[IO.Path]::GetFullPath($JobRoot)
if(-not$JobRoot.StartsWith('D:\CodexLab\',[StringComparison]::OrdinalIgnoreCase)){throw'JobRoot outside D:\CodexLab'}
$out=Join-Path $JobRoot 'output\disassembly-v1';if(Test-Path $out){throw"Output exists: $out"};New-Item -ItemType Directory -Path $out|Out-Null
$cuda=$env:CUDA_PATH;if(-not$cuda){$cuda='C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v13.3'};$tool=Join-Path $cuda 'bin\cuobjdump.exe';$rows=@()
foreach($token in @(22,24)){$input=Join-Path $JobRoot ('inputs\cu-module-{0:D6}.bin'-f$token);if(-not(Test-Path $input)){throw"Missing $input"};$ptx=Join-Path $out ('module-{0:D6}.ptx.txt'-f$token);$sass=Join-Path $out ('module-{0:D6}.sass.txt'-f$token);&$tool --dump-ptx $input|Set-Content -Encoding utf8 $ptx;&$tool --dump-sass $input|Set-Content -Encoding utf8 $sass;$rows+=[ordered]@{module_token=$token;input_bytes=(Get-Item $input).Length;input_sha256=(Get-FileHash $input -Algorithm SHA256).Hash.ToLowerInvariant();ptx_sha256=(Get-FileHash $ptx -Algorithm SHA256).Hash.ToLowerInvariant();sass_sha256=(Get-FileHash $sass -Algorithm SHA256).Hash.ToLowerInvariant()}}
$receipt=[ordered]@{schema='neuralstudio.fg.resolution-l22-l24-disassembly.v1';job_id=Split-Path -Leaf $JobRoot;gpu=(&nvidia-smi --query-gpu=name,driver_version --format=csv,noheader|select -First 1).Trim();cuda=(&$tool --version|select -Last 1).Trim();modules=$rows;address_fields_recorded=$false;result='pass'};$utf8=New-Object Text.UTF8Encoding($false);$path=Join-Path $out 'receipt.json';[IO.File]::WriteAllText($path,(($receipt|ConvertTo-Json -Depth 5)+"`n"),$utf8);Write-Host "output=$out";Write-Host "receipt_sha256=$((Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant())";Write-Host result=pass
